"""Home madura do VighnaStudy (H35 R3 — correção de geometria).

A interface desenha apenas a página inicial com Qt/QPainter. Não toca na
sidebar, banco de dados, histórico, motor de estudo ou regras de perfil.
O cabeçalho compartilhado continua o mesmo widget/código do Dashboard;
nenhum QComboBox ou sinal é duplicado.
"""

import base64
import math
from PySide6.QtCore import Qt, QRectF, QPointF
from PySide6.QtGui import (
    QColor, QPainter, QPainterPath, QLinearGradient, QRadialGradient,
    QPen, QBrush, QFont, QFontMetrics, QPixmap, QPolygonF
)
from PySide6.QtWidgets import (
    QWidget, QPushButton, QAbstractButton, QLabel, QFrame, QScrollArea,
    QHBoxLayout, QVBoxLayout, QSizePolicy, QMenu
)

_SYMBOL_B64 = ""


def _cor(valor):
    return QColor(valor)


def _font(tamanho, peso=QFont.Normal, familia="Segoe UI"):
    fonte = QFont(familia)
    fonte.setPixelSize(max(9, int(tamanho)))
    fonte.setWeight(peso)
    return fonte


class FundoHomeMaduro(QWidget):
    """Cenário estático, dimensionado ao espaço à direita da sidebar."""

    def definir_reducao_movimento(self, *args, **kwargs):
        # Não existe animação periódica nesta Home.
        return None

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing, True)
        w = float(self.width()); h = float(self.height())
        if w < 2 or h < 2:
            p.end(); return

        base = QLinearGradient(0, 0, w, h)
        base.setColorAt(0.0, _cor("#06192b"))
        base.setColorAt(0.48, _cor("#03172a"))
        base.setColorAt(1.0, _cor("#04172a"))
        p.fillRect(self.rect(), base)

        # Vinheta azul central discreta.
        halo = QRadialGradient(QPointF(w * .51, h * .45), max(w, h) * .68)
        halo.setColorAt(0, QColor(0, 90, 150, 40))
        halo.setColorAt(1, QColor(0, 15, 34, 0))
        p.fillRect(self.rect(), QBrush(halo))

        # Superfícies geométricas superiores à esquerda, como a referência.
        topo = QPainterPath()
        topo.moveTo(0, 0)
        topo.lineTo(w * .31, 0)
        topo.cubicTo(w*.19,h*.07,w*.14,h*.15,0,h*.27)
        topo.closeSubpath()
        topo_cor = QLinearGradient(0, 0, w*.30, h*.34)
        topo_cor.setColorAt(0, QColor(4, 49, 79, 242))
        topo_cor.setColorAt(1, QColor(7, 71, 114, 110))
        p.fillPath(topo, topo_cor)

        aba = QPainterPath()
        aba.moveTo(0, h*.23)
        aba.cubicTo(w*.09,h*.09,w*.19,h*.03,w*.28,0)
        aba.lineTo(w*.37,0)
        aba.cubicTo(w*.22,h*.12,w*.10,h*.24,0,h*.43)
        aba.closeSubpath()
        p.fillPath(aba, QColor(2, 26, 49, 156))
        p.setPen(QPen(QColor(17, 132, 184, 100), 1.0))
        p.drawPath(topo)

        # Ondas geométricas inferiores à direita (sem bordas pesadas).
        inferior = QPainterPath()
        inferior.moveTo(w*.50, h)
        inferior.cubicTo(w*.69,h*.85,w*.88,h*.90,w,h*.72)
        inferior.lineTo(w,h)
        inferior.closeSubpath()
        baixo = QLinearGradient(w*.6,h*.86,w,h)
        baixo.setColorAt(0, QColor(3, 43, 76, 85))
        baixo.setColorAt(1, QColor(5, 90, 139, 200))
        p.fillPath(inferior,baixo)
        p.setPen(QPen(QColor(0, 180, 243, 103), 1.2))
        p.drawPath(inferior)
        baixo_2=QPainterPath()
        baixo_2.moveTo(w*.74,h)
        baixo_2.cubicTo(w*.87,h*.92,w*.98,h*.88,w,h*.82)
        baixo_2.lineTo(w,h)
        baixo_2.closeSubpath()
        p.fillPath(baixo_2,QColor(0, 50, 90, 123))
        p.setPen(QPen(QColor(14, 118, 182, 105), 1.0))
        p.drawPath(baixo_2)
        p.end()


class LogoHomeMaduro(QWidget):
    """Marca composta com o símbolo fornecido no mockup e tipografia Qt."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumHeight(178)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        self._simbolo = QPixmap()
        try:
            self._simbolo.loadFromData(base64.b64decode(_SYMBOL_B64), "PNG")
        except (ValueError, TypeError):
            pass

    def paintEvent(self, event):
        p=QPainter(self)
        p.setRenderHint(QPainter.Antialiasing,True)
        w=float(self.width());h=float(self.height())
        # Cabe em 980px até 1680px de janela sem truncamento.
        font_px=min(72,max(39,int(w*.052)))
        fonte=_font(font_px,QFont.Bold)
        p.setFont(fonte)
        fm=QFontMetrics(fonte)
        esquerda="Vighna"; direita="Study"
        ww1=fm.horizontalAdvance(esquerda);ww2=fm.horizontalAdvance(direita)
        icw=min(156, max(94,int(font_px*2.1)))
        total=icw+10+ww1+ww2
        # Se uma resolução mais estreita ocorrer, reduz proporcionalmente.
        if total>w*.96:
            escala=(w*.96)/total
            font_px=int(font_px*escala)
            fonte=_font(font_px,QFont.Bold);p.setFont(fonte)
            fm=QFontMetrics(fonte)
            ww1=fm.horizontalAdvance(esquerda);ww2=fm.horizontalAdvance(direita)
            icw=int(icw*escala)
            total=icw+10+ww1+ww2
        x=(w-total)/2.0
        marca_h=min(136,h*.68)
        if not self._simbolo.isNull():
            target=QRectF(x,4,icw,marca_h)
            pm=self._simbolo.scaled(int(target.width()),int(target.height()),
                                    Qt.KeepAspectRatio,Qt.SmoothTransformation)
            p.drawPixmap(QPointF(x+(icw-pm.width())/2,4+(marca_h-pm.height())/2),pm)
        baseline=5+(marca_h+font_px)/2.0+8
        p.setFont(fonte)
        p.setPen(QColor(238,246,255,54))
        p.drawText(QPointF(x+icw+11+1,baseline+1),esquerda+direita)
        p.setPen(QColor("#F4F7FD"))
        p.drawText(QPointF(x+icw+10,baseline),esquerda)
        grad=QLinearGradient(x+icw+ww1,0,x+icw+ww1+ww2,0)
        grad.setColorAt(0,QColor("#8FEFFF"))
        grad.setColorAt(.60,QColor("#23CBF7"))
        grad.setColorAt(1,QColor("#00A9E6"))
        p.setPen(QPen(QBrush(grad),1))
        p.drawText(QPointF(x+icw+10+ww1,baseline),direita)
        # Assinatura superior, com traços ciano dos dois lados.
        subtitulo="S I S T E M A   D E   E S T U D O S   A V A N Ç A D O"
        sub_font=_font(min(20,max(10,int(w*.015))),QFont.Medium)
        p.setFont(sub_font)
        metrics=QFontMetrics(sub_font)
        tw=metrics.horizontalAdvance(subtitulo)
        if tw>w*.77:
            sub_font=_font(max(9,int(sub_font.pixelSize()*(w*.77)/tw)),QFont.Medium)
            p.setFont(sub_font);tw=QFontMetrics(sub_font).horizontalAdvance(subtitulo)
        mid=w/2;y=h-21
        p.setPen(QColor("#E0EAF7"))
        p.drawText(QRectF(mid-tw/2,h-48,tw,32),Qt.AlignCenter,subtitulo)
        gap=24
        p.setPen(QPen(QColor("#05CAE9"),2.2))
        p.drawLine(QPointF(max(0,mid-tw/2-gap-72),y-16),QPointF(mid-tw/2-gap,y-16))
        p.drawLine(QPointF(mid+tw/2+gap,y-16),QPointF(min(w,mid+tw/2+gap+72),y-16))
        p.end()


class CartaoHomeMaduro(QAbstractButton):
    """Botão acessível clicável com pintura própria, isolado dos QSS de QPushButton.

    QAbstractButton mantém clicked, Enter/Espaço, mouse e foco sem depender
    das regras globais de tamanho dos QPushButton do programa.
    """

    def __init__(self,titulo,descricao,tipo,callback,parent=None):
        super().__init__(parent)
        self.titulo=titulo
        self.descricao=descricao
        self.tipo=tipo
        self._hover=False
        self.setObjectName("homeMaduroCard_"+tipo)
        self.setCursor(Qt.PointingHandCursor)
        self.setFocusPolicy(Qt.StrongFocus)
        self.setSizePolicy(QSizePolicy.Expanding,QSizePolicy.Fixed)
        self.setMinimumWidth(225)
        # Evita a altura ~38px observada quando a folha QSS global comprime botões.
        self.setFixedHeight(270)
        self.setToolTip(titulo+" — "+descricao)
        self.setAccessibleName(titulo)
        if callback is not None:
            self.clicked.connect(callback)
        else:
            self.setEnabled(False)

    def enterEvent(self,event):
        self._hover=True
        self.update()
        super().enterEvent(event)

    def leaveEvent(self,event):
        self._hover=False
        self.update()
        super().leaveEvent(event)

    def focusInEvent(self,event):
        super().focusInEvent(event)
        self.update()

    def focusOutEvent(self,event):
        super().focusOutEvent(event)
        self.update()

    @staticmethod
    def _desenhar_icone(p,tipo,cx,cy,tamanho):
        p.save()
        p.translate(cx,cy)
        p.scale(tamanho/100.0,tamanho/100.0)
        p.setBrush(Qt.NoBrush)
        branco=QColor("#F0F5FA");ciano=QColor("#08CFFF")
        if tipo=="estudo":
            # Livro aberto, páginas sobrepostas, com base iluminada.
            p.setPen(QPen(ciano,5,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            brilho=QPainterPath()
            brilho.moveTo(-51,28);brilho.lineTo(-51,-25)
            brilho.lineTo(-41,-24)
            p.drawPath(brilho)
            p.drawLine(QPointF(51,28),QPointF(51,-25))
            p.setPen(QPen(branco,5,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            livro=QPainterPath()
            livro.moveTo(0,29)
            livro.cubicTo(-14,14,-27,8,-42,11)
            livro.lineTo(-42,-33)
            livro.cubicTo(-22,-39,-10,-29,0,-21)
            livro.cubicTo(10,-29,22,-39,42,-33)
            livro.lineTo(42,11)
            livro.cubicTo(27,8,14,14,0,29)
            p.drawPath(livro)
            p.setPen(QPen(ciano,4,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            p.drawLine(QPointF(-48,29),QPointF(0,36))
            p.drawLine(QPointF(0,36),QPointF(48,29))
        elif tipo=="simulados":
            p.setPen(QPen(branco,5,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            p.drawRoundedRect(QRectF(-31,-39,62,78),7,7)
            p.drawRoundedRect(QRectF(-13,-45,26,13),5,5)
            for y in (-17,6):
                p.setPen(QPen(ciano,5,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
                p.drawLine(QPointF(-19,y),QPointF(-14,y+5))
                p.drawLine(QPointF(-14,y+5),QPointF(-6,y-7))
                p.setPen(QPen(branco,4,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
                p.drawLine(QPointF(3,y),QPointF(21,y))
            p.drawLine(QPointF(3,28),QPointF(21,28))
        elif tipo=="edital":
            p.setPen(QPen(branco,5,Qt.SolidLine,Qt.RoundCap,Qt.RoundJoin))
            folha=QPainterPath()
            folha.moveTo(-35,-41);folha.lineTo(13,-41)
            folha.lineTo(35,-19);folha.lineTo(35,36)
            folha.quadTo(35,41,30,41)
            folha.lineTo(-35,41)
            folha.closeSubpath()
            p.drawPath(folha)
            p.drawLine(QPointF(13,-41),QPointF(13,-19))
            p.drawLine(QPointF(13,-19),QPointF(35,-19))
            for y in (-18,-5,8):
                p.drawLine(QPointF(-22,y),QPointF(14,y))
            # Estrela dourada - elemento pontual da marca.
            estrela=QPolygonF()
            for i in range(10):
                ang=-math.pi/2+i*math.pi/5
                raio=24 if i%2==0 else 10
                estrela.append(QPointF(26+math.cos(ang)*raio,24+math.sin(ang)*raio))
            p.setPen(Qt.NoPen)
            p.setBrush(QColor("#F6B641"))
            p.drawPolygon(estrela)
        p.restore()

    def paintEvent(self,event):
        p=QPainter(self)
        p.setRenderHint(QPainter.Antialiasing,True)
        w=float(self.width());h=float(self.height())
        destaque=self.tipo=="estudo" or self._hover or self.hasFocus()
        rect=QRectF(3,3,w-6,h-6)
        fill=QLinearGradient(0,0,w,h)
        fill.setColorAt(0,QColor("#10405d") if destaque else QColor("#102f49"))
        fill.setColorAt(.60,QColor("#0A263E"))
        fill.setColorAt(1,QColor("#061d33"))
        p.setPen(Qt.NoPen)
        p.setBrush(fill)
        p.drawRoundedRect(rect,29,29)
        # Traço único e discreto evita borda dupla no foco.
        cor_borda=QColor("#13DDF6") if destaque else QColor("#507FA0")
        p.setPen(QPen(cor_borda,2.1 if destaque else 1.6))
        p.setBrush(Qt.NoBrush)
        p.drawRoundedRect(rect,29,29)
        # Iluminação suave no centro superior do cartão.
        glow=QRadialGradient(QPointF(w/2,h*.30),w*.57)
        glow.setColorAt(0,QColor(6,137,194,33 if destaque else 19))
        glow.setColorAt(1,QColor(0,34,50,0))
        p.setPen(Qt.NoPen);p.setBrush(glow)
        p.drawRoundedRect(rect.adjusted(4,4,-4,-4),25,25)

        icon_size=min(100,max(64,int(h*.32)))
        self._desenhar_icone(p,self.tipo,w/2,h*.32,icon_size)
        titulo_px=min(35,max(23,int(w*.085)))
        titulo_f=_font(titulo_px,QFont.Bold)
        if QFontMetrics(titulo_f).horizontalAdvance(self.titulo)>w-27:
            titulo_f=_font(int(titulo_px*.85),QFont.Bold)
        p.setFont(titulo_f)
        p.setPen(QColor("#F8FBFF"))
        p.drawText(QRectF(12,h*.54,w-24,h*.15),Qt.AlignHCenter|Qt.AlignVCenter,self.titulo)
        desc_f=_font(min(19,max(13,int(w*.047))),QFont.Normal)
        if QFontMetrics(desc_f).horizontalAdvance(self.descricao)>w-27:
            desc_f=_font(max(12,int(desc_f.pixelSize()*.86)),QFont.Normal)
        p.setFont(desc_f);p.setPen(QColor("#C9DBEA"))
        p.drawText(QRectF(8,h*.70,w-16,h*.12),Qt.AlignHCenter|Qt.AlignVCenter,self.descricao)
        p.setPen(QPen(QColor("#00D7F1"),4,Qt.SolidLine,Qt.RoundCap))
        p.drawLine(QPointF(w*.36,h*.89),QPointF(w*.64,h*.89))
        p.end()


def criar_portal_inicio(abrir_dashboard, abrir_busca, abrir_questoes,
                        abrir_simulados=None, abrir_recursos=None,
                        cabecalho_compartilhado=None, abrir_edital=None):
    """Mantém o contrato original e os destinos; nenhum novo motor acadêmico."""
    pagina=QWidget()
    pagina.setObjectName("portalInicioPage")
    pagina.setSizePolicy(QSizePolicy.Expanding,QSizePolicy.Expanding)
    raiz=QVBoxLayout(pagina)
    raiz.setContentsMargins(0,0,0,0)
    raiz.setSpacing(0)
    scroll=QScrollArea(pagina)
    scroll.setObjectName("portalInicioScroll")
    scroll.setFrameShape(QFrame.NoFrame)
    scroll.setWidgetResizable(True)
    scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
    conteudo=FundoHomeMaduro()
    conteudo.setObjectName("portalInicioConteudo")
    conteudo.setMinimumSize(795,660)
    coluna=QVBoxLayout(conteudo)
    coluna.setContentsMargins(52,22,52,30)
    coluna.setSpacing(0)

    header=QHBoxLayout()
    header.setContentsMargins(0,0,0,0)
    header.addStretch(1)
    if cabecalho_compartilhado is not None:
        # Mesmo perfil, mesmo QComboBox e mesmas ligações. Sem duplicação.
        cabecalho_compartilhado.setFixedWidth(363)
        cabecalho_compartilhado.setFixedHeight(83)
        cabecalho_compartilhado.setObjectName("dashboardTopBar")
        gerenciar=cabecalho_compartilhado.findChild(QPushButton,"premiumHeaderManageButton")
        if gerenciar is not None:
            # Evita botão extra no mockup, preservando a ação real no menu.
            gerenciar.hide()
            cabecalho_compartilhado.setToolTip(
                "Perfil ativo — botão direito para gerenciar perfis"
            )
            cabecalho_compartilhado.setContextMenuPolicy(Qt.CustomContextMenu)
            def _abrir_gerenciamento(pos, _botao=gerenciar,
                                    _cabecalho=cabecalho_compartilhado):
                menu = QMenu(_cabecalho)
                opcao = menu.addAction("Gerenciar perfis")
                escolhido = menu.exec(_cabecalho.mapToGlobal(pos))
                if escolhido is opcao:
                    _botao.click()
            cabecalho_compartilhado.customContextMenuRequested.connect(
                _abrir_gerenciamento
            )
        header.addWidget(cabecalho_compartilhado,0,Qt.AlignRight|Qt.AlignTop)
        pagina.portal_perfil_label=None
        pagina._home_cabecalho_compartilhado=cabecalho_compartilhado
    else:
        rotulo=QLabel("Perfil ativo",conteudo)
        rotulo.setObjectName("homeFallbackPerfil")
        header.addWidget(rotulo)
        pagina.portal_perfil_label=rotulo
    coluna.addLayout(header)
    coluna.addSpacing(8)

    logo=LogoHomeMaduro(conteudo)
    logo.setFixedHeight(195)
    coluna.addWidget(logo)
    coluna.addSpacing(28)

    # Contêiner de altura explícita: o layout vertical não pode comprimir a
    # faixa dos três cartões para a altura de um QPushButton convencional.
    faixa_cartoes=QWidget(conteudo)
    faixa_cartoes.setObjectName("portalInicioCardsContainer")
    faixa_cartoes.setSizePolicy(QSizePolicy.Expanding,QSizePolicy.Fixed)
    faixa_cartoes.setFixedHeight(270)
    cards=QHBoxLayout(faixa_cartoes)
    cards.setSpacing(22)
    cards.setContentsMargins(0,0,0,0)
    especificacoes=(
        ("Iniciar Estudo","Disciplinas, tópicos e questões","estudo",abrir_dashboard),
        ("Simulados","Avalie seus conhecimentos","simulados",abrir_simulados),
        ("Meu Edital","Acompanhe conteúdos e cobertura","edital",abrir_edital),
    )
    pagina._home_cards=[]
    for titulo,descricao,tipo,abrir in especificacoes:
        cartao=CartaoHomeMaduro(titulo,descricao,tipo,abrir,conteudo)
        cartao.setFixedHeight(270)
        cards.addWidget(cartao,1)
        pagina._home_cards.append(cartao)
    coluna.addWidget(faixa_cartoes,0)
    pagina._home_faixa_cartoes=faixa_cartoes
    coluna.addStretch(1)
    coluna.addSpacing(20)
    scroll.setWidget(conteudo)
    raiz.addWidget(scroll,1)
    pagina._home_scroll=scroll
    pagina._home_conteudo=conteudo
    pagina._home_maduro=True
    return pagina


def aplicar_estilo_portal(pagina, tema):
    """QSS restrito à Home; Qt/QPainter controla o visual dos cartões."""
    pagina.setStyleSheet("""
    QWidget#portalInicioPage { background: #03172a; border: none; }
    QScrollArea#portalInicioScroll { background: transparent; border: none; }
    QWidget#portalInicioConteudo { border: none; }
    QLabel#homeFallbackPerfil { color: #eef8ff; font-size: 16px; }
    QScrollBar:vertical { background: #071a2c; width: 7px; margin: 0; }
    QScrollBar::handle:vertical { background: #1e587d; border-radius: 3px; min-height: 28px; }
    QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
    """)
    header=getattr(pagina,"_home_cabecalho_compartilhado",None)
    if header is not None:
        estilizar_perfil_maduro(header)


def estilizar_perfil_maduro(painel):
    """Aplica estética compacta ao cabeçalho ORIGINAL (mesmo seletor)."""
    painel.setStyleSheet("""
    QFrame#dashboardTopBar {
        background: rgba(7, 33, 55, 232);
        border: 1px solid #3f7da2;
        border-radius: 17px;
    }
    QFrame#dashboardTopBar QFrame#topProfileBar {
        background: transparent; border: none; border-radius: 0px;
    }
    QFrame#dashboardTopBar QLabel#topProfileLabel {
        background: transparent; color: #c6d8e9;
        font-size: 12px; font-weight: 500; padding: 0px;
    }
    QFrame#dashboardTopBar QLabel#premiumHeaderProfileIcon {
        color: #e5f4ff; background: transparent; border: none;
    }
    QFrame#dashboardTopBar QComboBox#topProfileCombo {
        background: transparent; color: #f8fcff;
        border: none; font-size: 18px; font-weight: 700;
        padding-left: 0px; padding-top: 0px;
    }
    QFrame#dashboardTopBar QComboBox#topProfileCombo::drop-down {
        width: 26px; border: none;
    }
    QFrame#dashboardTopBar QComboBox#topProfileCombo:hover,
    QFrame#dashboardTopBar QComboBox#topProfileCombo:focus {
        background: rgba(25, 82, 115, 110);
    }
    """)
    # Reaproveita o layout original e conserva todos os sinais do perfil.
    lay=painel.layout()
    if lay is not None:
        lay.setContentsMargins(14, 8, 9, 8)
        lay.setSpacing(3)
    profile=painel.findChild(QFrame,"topProfileBar")
    if profile is not None:
        profile.setMinimumWidth(265)
        profile.setMaximumWidth(330)
        pl=profile.layout()
        if pl is not None:
            pl.setContentsMargins(4,3,4,3)
            pl.setSpacing(11)
        from PySide6.QtWidgets import QComboBox
        combo=profile.findChild(QComboBox,"topProfileCombo")
        if combo is not None:
            combo.setMinimumWidth(200)
            combo.setMaximumWidth(280)
            combo.setFixedHeight(31)
    return painel
